from gen_common import generate
from score_topic import score

random.seed(42)

def M(q, o, a, e, d):
    return (q, o, a, e, d)

# ============== TOPIC DEFINITIONS ==============
# Each topic: (id, name, order, summary, extra_questions_for_mcq)

def q_bank(qs):
    """Convert (q, correct, wrongs, explanation, diff) to MCQ tuples."""
    out = []
    for q, c, ws, e, d in qs:
        opts = list(ws) + [c]
        random.shuffle(opts)
        ci = opts.index(c)
        out.append(M(q, opts, ci, e, d))
    return out

