t1_sidebar = '"শিল্পবিপ্লব" (Industrial Revolution) শব্দটি প্রথম ব্যবহার করেন ফরাসি সমাজতত্ত্ববিদ অগাস্ট ব্লাংকি ১৮৩৭ সালে। কার্ল মার্কস দাস ক্যাপিটাল (১৮৬৭)-এ প্রয়োগ করেন। আর্নল্ড টয়েনবি অক্সফোর্ড বক্তৃতায় (১৮৮০-৮১) জনপ্রিয় করেন। তাঁর মতে শিল্পবিপ্লবের সূচনা ১৭৬০ সালে, হফম্যানের মতে ১৭৮০ সালে।'
t1_real = 'ধরো, তুমি আগে হাতে কলম দিয়ে একটি পৃষ্ঠা লিখতে ১০ মিনিট নিতে। এখন প্রিন্টার থাকলে ১ মিনিটে ১০০ পৃষ্ঠা ছাপানো যায়। এই পরিবর্তন — হাতের কাজ থেকে মেশিনের কাজ — এটাই শিল্পবিপ্লব।'
